import math

def count_pairs(n):
    def get_v_p(n, p):
        count = 0
        while n > 0:
            count += n // p
            n //= p
        return count

    g = 2023
    # Check if g divides n!
    # 2023 = 7 * 17^2
    if get_v_p(n, 7) < 1 or get_v_p(n, 17) < 2:
        return 0

    # Number of prime factors of K = n! / (7 * 17^2)
    # omega(K) = count of p <= n such that v_p(n!) - v_p(2023) > 0
    omega_K = 0
    primes = []
    # We only need primes up to n
    for i in range(2, n + 1):
        is_prime = True
        for p in primes:
            if i % p == 0:
                is_prime = False
                break
        if is_prime:
            primes.append(i)

    for p in primes:
        v_p_n_fact = get_v_p(n, p)
        v_p_2023 = 0
        if p == 7:
            v_p_2023 = 1
        elif p == 17:
            v_p_2023 = 2

        if v_p_n_fact - v_p_2023 > 0:
            omega_K += 1

    return 2**omega_K

results = []
for n in range(1, 100):
    count = count_pairs(n)
    results.append((n, count))

for n, count in results:
